import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import '../../../../app/providers.dart'; import '../../../../core/theme/app_colors.dart';
class AiScreen extends ConsumerStatefulWidget{const AiScreen({super.key});@override ConsumerState<AiScreen> createState()=>_S();}
class _S extends ConsumerState<AiScreen>{String kind='date';String result='';bool busy=false;final prompt=TextEditingController();final kinds={'date':'Date idea','love-note':'Love note','memory-caption':'Memory caption','anniversary':'Anniversary idea','gift':'Gift idea','conversation':'Conversation starter','bucket-list':'Bucket-list idea','trip':'Trip idea','game':'Game idea'};
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('143 AI')),body:ListView(padding:const EdgeInsets.all(20),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:AppColors.blush,borderRadius:BorderRadius.circular(24)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.auto_awesome,color:AppColors.rose),SizedBox(height:10),Text('Private by choice',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),SizedBox(height:6),Text('AI only uses personal couple content when you explicitly allow it.')])),const SizedBox(height:18),DropdownButtonFormField(value:kind,items:kinds.entries.map((e)=>DropdownMenuItem(value:e.key,child:Text(e.value))).toList(),onChanged:(v)=>setState(()=>kind=v!)),const SizedBox(height:12),TextField(controller:prompt,maxLines:3,decoration:const InputDecoration(labelText:'Optional context',hintText:'e.g. quiet evening at home, low budget')),const SizedBox(height:14),FilledButton.icon(onPressed:busy?null:_generate,icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.auto_awesome),label:const Text('Generate suggestion')),if(result.isNotEmpty)...[const SizedBox(height:20),Card(child:Padding(padding:const EdgeInsets.all(20),child:SelectableText(result,style:const TextStyle(fontSize:16,height:1.5))))]]));
Future<void>_generate()async{setState(()=>busy=true);try{final v=await ref.read(advancedRepositoryProvider).aiSuggestion(kind,prompt:prompt.text);setState(()=>result=v is Map?(v['text']??v['suggestion']??v).toString():v.toString());}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}
}
